files.agent-pane/theme.css:
/* Omnibar's chat: a page under browser chrome. The prompt is a field the shape of the address
   field's parent (14 px corners: 8 px buttons 6 px from its edge), cards are the hover fill with
   a hairline, links are the accent a step toward the text. Secondary text is solid ink, the
   text mixed into the page and never see-through, so it keeps its colour on a card or a bubble:
   muted at 76% (6.59:1 on Omnibar's page, 7.54:1 in Dark), dim at 70% (5.43:1, 6.64:1).
   "Worked for" and tool rows do not read these tokens (README, What a look cannot set yet).
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root. Every
   colour is mixed from the theme's own (--agent-text, --agent-accent, --agent-page-bg), so it
   reads over Omnibar, Omnibar Dark and any theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-text) 6%, transparent);
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 14px;
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 4%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 76%, var(--agent-page-bg));
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 70%, var(--agent-page-bg));
  --cv-link: color-mix(in srgb, var(--agent-accent) 76%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 76%, var(--agent-text));

  /* Pending cmux#46846 (--menu-*): menus and popovers. Inert until it lands.
     A menu is the address field's popup: 12 px corners (8 px rows 4 px from its edge), 28 px
     rows, the highlighted row the hover fill with 8 px corners, separators inset 8 px. */
  --menu-radius: 12px;
  --menu-padding: 4px;
  --menu-fill: var(--agent-page-bg);
  --menu-border: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --menu-row-height: 28px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-text) 8%, transparent);
  --menu-hover-radius: 8px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --menu-separator-inset: 8px;
  --menu-label-color: color-mix(in srgb, var(--agent-text) 70%, var(--agent-page-bg));
  --menu-label-weight: 600;
  --menu-label-size: var(--text-caption);
  --menu-shortcut-color: color-mix(in srgb, var(--agent-text) 70%, var(--agent-page-bg));
  --menu-subtitle-color: color-mix(in srgb, var(--agent-text) 70%, var(--agent-page-bg));
  --menu-disabled-opacity: 0.4;
  --menu-submenu-offset: -4px;
  --menu-submenu-align-offset: -4px;
}

files.markdown/theme.css:
/* Omnibar's Markdown viewer: a page. Semibold headings with no rule, code on the hover fill with
   the root 8 px corner, quotes on a hairline.
   Only --cmux-md-* custom properties on :root; every colour is mixed from the page's own. */
:root {
  --cmux-md-code-background: color-mix(in srgb, var(--page-text) 4%, transparent);
  --cmux-md-code-radius: 8px;
  --cmux-md-heading-weight: 600;
  --cmux-md-heading-rule: none;
  --cmux-md-quote-border: 2px solid var(--cmux-md-border-color);
}

